// Declared capability ceilings for preset templates. Phase 0 does not enforce.

const SHIPPED_PRESET_IDS = ['standard', 'code', 'minimal', 'cordis']
const TEMPLATE_ID = 'wa-template'
const TEMPLATE_NAME = 'claw区agent模板'
const TEMPLATE_LEGACY_NAMES = ['工作区 Agent 模板', '工作区agent模板']
const TEMPLATE_SOURCE_CANDIDATES = ['standard', 'code']

function presetIdForWorkspace(workspaceId) {
  return 'wa-' + String(workspaceId)
}

function isShippedPreset(id) {
  return SHIPPED_PRESET_IDS.includes(id)
}

function isClawPresetId(id) {
  if (typeof id !== 'string' || id === '') return false
  if (id === TEMPLATE_ID) return true
  if (isShippedPreset(id)) return false
  return id.startsWith('wa-')
}

function fallbackMissingPreset(id, liveIds, defaultId = 'standard') {
  if (id == null || id === '') return id
  const live = liveIds instanceof Set ? liveIds : new Set(liveIds || [])
  if (live.has(id)) return id
  if (isClawPresetId(id)) return defaultId || 'standard'
  return id
}

function aliasClawPresetId(id, defaultId = 'standard') {
  if (!isClawPresetId(id)) return id
  const fallback = defaultId || 'standard'
  return isClawPresetId(fallback) ? 'standard' : fallback
}

function rewriteTemplatePresetYaml(text, name) {
  const line = 'name: ' + name
  if (typeof text !== 'string' || text === '') return line + '\n'
  if (/^name:\s*.+$/m.test(text)) return text.replace(/^name:\s*.+$/m, line)
  return line + '\n' + text
}

function siblingFile(path, name) {
  const raw = String(path || '')
  const dir = raw.replace(/[/\\][^/\\]+$/, '')
  if (!dir || dir === raw) return String(name || '')
  const sep = raw.includes('\\') ? '\\' : '/'
  return dir + sep + String(name || '')
}

async function ensureTemplateNamed(presets, io) {
  const list = await presets.list()
  const template = list.find((row) => row && row.id === TEMPLATE_ID)
  if (template == null) return { changed: false }
  if (template.name === TEMPLATE_NAME) return { changed: false }
  if (template.path == null || io == null || typeof io.readFile !== 'function') {
    return { changed: false }
  }
  const file = siblingFile(template.path, 'preset.yml')
  const text = await io.readFile(file, 'utf8')
  const next = rewriteTemplatePresetYaml(text, TEMPLATE_NAME)
  if (next === text) return { changed: false }
  await io.writeFile(file, next)
  return { changed: true, file }
}

function openPersonaYaml(text) {
  if (typeof text !== 'string' || text === '') return text
  return text.replace(/^(\s*)complete:\s*true\s*$/m, '$1complete: false')
}

async function ensureOpenPersona(presets, io) {
  if (presets == null || typeof presets.list !== 'function' || io == null) return { changed: 0 }
  const list = await presets.list()
  let changed = 0
  for (const row of list) {
    if (!row || !isClawPresetId(row.id) || !row.path) continue
    try {
      const text = await io.readFile(row.path, 'utf8')
      const next = openPersonaYaml(text)
      if (next !== text) {
        await io.writeFile(row.path, next)
        changed += 1
      }
    } catch { /* missing composition */ }
  }
  return { changed }
}

/**
 * Unset volatile selectedDefault when it points at a Claw wa-* / template preset.
 * Namespace is agent-preset-registry (0.2+); path is selectedDefault only.
 */
async function clearSelectedClawDefault(settings, selectedDefault, expectedRevision) {
  if (!isClawPresetId(selectedDefault)) return { cleared: false }
  if (settings == null || typeof settings.mutate !== 'function') {
    return { cleared: false, skipped: true }
  }
  const args = expectedRevision === undefined
    ? ['agent-preset-registry', [{ op: 'unset', path: ['selectedDefault'] }]]
    : ['agent-preset-registry', [{ op: 'unset', path: ['selectedDefault'] }], expectedRevision]
  await settings.mutate(...args)
  return { cleared: true }
}

/** @deprecated Prefer clearSelectedClawDefault */
async function clearClawDefault(settings, selectedDefault, expectedRevision) {
  return clearSelectedClawDefault(settings, selectedDefault, expectedRevision)
}

function isIsolatedMinimalClone(text) {
  const src = String(text || '')
  return src.includes('dsh-tool-bash-persistent') || src.includes('dsh-tool-str-replace-editor')
}

async function rewriteIsolatedMinimalClones(presets, io) {
  if (presets == null || typeof presets.list !== 'function' || io == null) return { repaired: [] }
  const list = await presets.list()
  const source = list.find((row) => row && TEMPLATE_SOURCE_CANDIDATES.includes(row.id) && row.path)
  if (!source) return { repaired: [] }
  let body = ''
  try {
    body = await io.readFile(source.path, 'utf8')
  } catch {
    return { repaired: [] }
  }
  if (!body) return { repaired: [] }
  const repaired = []
  for (const row of list) {
    if (!row || !isClawPresetId(row.id) || !row.path) continue
    let text = ''
    try {
      text = await io.readFile(row.path, 'utf8')
    } catch {
      continue
    }
    if (!isIsolatedMinimalClone(text) || text === body) continue
    await io.writeFile(row.path, body)
    repaired.push(row.id)
  }
  return { repaired }
}

async function ensureGeneratedPreset(presets, spec) {
  const id = spec.id
  const name = spec.name
  if (isShippedPreset(id) || id === TEMPLATE_ID) {
    throw new Error('refusing to overwrite a shipped or template preset')
  }
  const list = await presets.list()
  const ids = new Set(list.map((row) => row.id))
  if (!ids.has(TEMPLATE_ID)) {
    const source = TEMPLATE_SOURCE_CANDIDATES.find((candidate) => ids.has(candidate))
    if (!source) throw new Error('no official preset to copy as template')
    await presets.copy(source, TEMPLATE_ID, TEMPLATE_NAME)
    ids.add(TEMPLATE_ID)
  }
  if (!ids.has(id)) {
    await presets.copy(TEMPLATE_ID, id, name || id)
  }
  return id
}

function normalizeModel(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null
  const provider = typeof raw.provider === 'string' ? raw.provider.trim() : ''
  const model = typeof raw.model === 'string' ? raw.model.trim() : ''
  if (!provider || !model) return null
  const effort = typeof raw.reasoningEffort === 'string' ? raw.reasoningEffort.trim() : ''
  return effort ? { provider, model, reasoningEffort: effort } : { provider, model }
}

function modelKey(selection) {
  const next = normalizeModel(selection)
  return next ? next.provider + '::' + next.model : 'inherit'
}

function hasLoggedModel(agent) {
  const session = agent && agent.session
  if (!session || typeof session.requestHeader !== 'function') return false
  try {
    const header = session.requestHeader()
    const config = header && header.config
    return !!(config && config.provider && config.model)
  } catch {
    return false
  }
}

function findClawAgent(registry, query) {
  const rows = registry && registry.agents ? Object.values(registry.agents) : []
  const cwd = query && query.cwd ? String(query.cwd) : ''
  const preset = query && query.preset ? String(query.preset) : ''
  for (const row of rows) {
    if (!row || row.status === 'archived') continue
    if (cwd && row.canonicalRoot && normalizePathKey(row.canonicalRoot) === normalizePathKey(cwd)) return row
  }
  if (preset && isClawPresetId(preset)) {
    for (const row of rows) {
      if (!row || row.status === 'archived') continue
      if (row.dshPreset === preset) return row
    }
  }
  return null
}

function currentClawBlankHint(snap) {
  if (!snap || !snap.current || !snap.byId) return null
  const row = snap.byId[snap.current]
  if (!row || row.blank !== true) return null
  const cwd = row.cwd || row.path || ''
  if (!isDsClawPath(cwd)) return null
  return { cwd, preset: row.agentPreset || '' }
}

function selectionForCurrentSession(registry, official, snap) {
  const hint = currentClawBlankHint(snap)
  if (!hint) return official
  const row = findClawAgent(registry, hint)
  const claw = row ? normalizeModel(row.model) : null
  return claw || official
}

function modelOfAgent(registry, agent) {
  if (!agent || !agent.session) return null
  const header = agent.session.header || {}
  const row = findClawAgent(registry, {
    cwd: header.cwd,
    preset: header.agentPreset,
  })
  return row ? normalizeModel(row.model) : null
}

function resolveBlankSelection(agent, official, clawModel) {
  if (!clawModel) return official
  if (hasLoggedModel(agent)) return official
  return clawModel
}

async function listModelCatalog(llm) {
  const groups = []
  if (!llm || typeof llm.listProviders !== 'function') return groups
  const providers = llm.listProviders() || []
  for (const provider of providers) {
    if (!provider || !provider.id) continue
    let models = []
    try {
      models = typeof llm.listModels === 'function' ? await llm.listModels(provider.id) : []
    } catch {
      models = []
    }
    const entries = []
    for (const item of Array.isArray(models) ? models : []) {
      if (!item || !item.id) continue
      let resolved = item
      if (typeof llm.resolveModelInfo === 'function') {
        try {
          resolved = await llm.resolveModelInfo(provider.id, item.id)
        } catch {
          resolved = item
        }
      }
      const reasoning = resolved && resolved.reasoning
      entries.push({
        id: item.id,
        name: item.name || item.id,
        description: item.description || '',
        reasoning: reasoning && Array.isArray(reasoning.efforts)
          ? {
            efforts: reasoning.efforts.map((effort) => ({
              id: effort.id,
              name: effort.name || effort.id,
              description: effort.description || '',
            })).filter((effort) => effort.id),
            defaultEffort: reasoning.defaultEffort || '',
          }
          : null,
      })
    }
    groups.push({
      id: provider.id,
      name: provider.name || provider.id,
      models: entries,
    })
  }
  return groups
}

function findCatalogModel(groups, provider, model) {
  for (const group of groups || []) {
    if (group.id !== provider) continue
    for (const item of group.models || []) {
      if (item.id === model) return { group, model: item }
    }
  }
  return null
}

function effortLabel(reasoning, effortId, fallback) {
  if (!reasoning) return fallback || ''
  const id = effortId || reasoning.defaultEffort
  if (!id) return fallback || ''
  const hit = (reasoning.efforts || []).find((row) => row.id === id)
  return hit ? hit.name : id
}

// Client-safe view helpers. No filesystem.

const CLAW_TEMPLATE_ID = 'wa-template'
const CLAW_TEMPLATE_NAMES = ['claw区agent模板', '工作区 Agent 模板', '工作区agent模板']

function isClawPresetId(id) {
  if (typeof id !== 'string' || id === '') return false
  if (id === CLAW_TEMPLATE_ID) return true
  if (id === 'standard' || id === 'code' || id === 'minimal' || id === 'cordis') return false
  return id.startsWith('wa-')
}

function clawAgents(projected) {
  return ((projected && projected.agents) || []).filter((agent) => (
    agent && agent.status !== 'archived' && agent.workspacePresent !== false
  ))
}

function clawPresetIds(projected) {
  const ids = new Set([CLAW_TEMPLATE_ID])
  for (const agent of (projected && projected.agents) || []) {
    if (agent && agent.dshPreset) ids.add(agent.dshPreset)
  }
  return ids
}

function clawHideNames(projected) {
  const names = new Set(CLAW_TEMPLATE_NAMES)
  for (const agent of (projected && projected.agents) || []) {
    if (agent && agent.title) names.add(String(agent.title))
    if (agent && agent.slug) names.add(String(agent.slug))
  }
  return names
}

function normalizePathKey(path) {
  return String(path || '').replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
}

function pathSetHas(paths, path) {
  if (!paths || !path) return false
  if (typeof paths.has === 'function' && paths.has(path)) return true
  const key = normalizePathKey(path)
  if (!key) return false
  if (typeof paths.has === 'function' && paths.has(key)) return true
  if (typeof paths[Symbol.iterator] !== 'function') return false
  for (const item of paths) {
    if (normalizePathKey(item) === key) return true
  }
  return false
}

function isDsClawPath(path) {
  if (typeof path !== 'string' || path === '') return false
  return /(^|\/)dsclaw(\/|$)/i.test(path.replace(/\\/g, '/'))
}

function clawHideKeys(projected) {
  const titles = new Set()
  const slugs = new Set()
  const paths = new Set()
  const sessionIds = new Set()
  const workspaceIds = new Set()
  for (const agent of (projected && projected.agents) || []) {
    if (!agent) continue
    if (agent.title) titles.add(String(agent.title))
    if (agent.slug) slugs.add(String(agent.slug))
    if (agent.canonicalRoot) {
      paths.add(String(agent.canonicalRoot))
      paths.add(normalizePathKey(agent.canonicalRoot))
    }
    if (agent.workspaceId) workspaceIds.add(String(agent.workspaceId))
    const ids = agent.sessionIds || []
    for (let i = 0; i < ids.length; i++) sessionIds.add(String(ids[i]))
  }
  return { titles, slugs, paths, sessionIds, workspaceIds }
}

function shouldHideOfficialGroup(title, clawTitlesOrKeys) {
  if (title == null || title === '') return false
  if (clawTitlesOrKeys instanceof Set) return clawTitlesOrKeys.has(title)
  const keys = clawTitlesOrKeys || {}
  if (keys.titles && keys.titles.has(title)) return true
  if (keys.slugs && keys.slugs.has(title)) return true
  return false
}

function isClawSessionFact(fact, keys) {
  if (fact == null || keys == null) return false
  if (fact.sessionId && keys.sessionIds && keys.sessionIds.has(String(fact.sessionId))) return true
  return isDsClawPath(fact.path || fact.cwd || '')
}

function isClawWorkspaceFact(fact, keys) {
  if (fact == null || keys == null) return false
  const raw = fact.path || fact.cwd || ''
  if (isDsClawPath(raw)) return true
  if (fact.workspaceId && keys.workspaceIds && keys.workspaceIds.has(String(fact.workspaceId))) return true
  if (raw && pathSetHas(keys.paths, raw)) return true
  if (raw) return false
  if (fact.sessionId && keys.sessionIds && keys.sessionIds.has(String(fact.sessionId))) return true
  if (!fact.workspaceId && fact.title && shouldHideOfficialGroup(fact.title, keys)) return true
  return false
}

function menuLabelStartsWithName(label, name) {
  if (!label || !name) return false
  if (label === name) return true
  if (label.indexOf(name + ' ·') === 0 || label.indexOf(name + ' ') === 0) return true
  if (label.indexOf(name) !== 0) return false
  const next = label.charAt(name.length)
  if (/[A-Za-z0-9_-]/.test(next)) return false
  return label.length >= name.length + 12
}

function isClawPresetMenuLabel(text, names) {
  const raw = String(text || '')
  const label = raw.replace(/\s+/g, ' ').trim()
  if (!label) return false
  const firstLine = raw.split(/\r?\n/)[0].replace(/\s+/g, ' ').trim()
  for (const name of names || []) {
    if (!name) continue
    if (menuLabelStartsWithName(label, name) || menuLabelStartsWithName(firstLine, name)) return true
  }
  return false
}

function selectableAgents(projected, labels) {
  const names = labels || {}
  const rows = []
  for (const agent of (projected && projected.agents) || []) {
    const title = agent.title || agent.canonicalRoot || agent.agentId
    const archived = agent.status === 'archived'
    rows.push({
      agentId: agent.agentId,
      kind: 'workspace',
      label: archived ? title + ' (' + (names.archived || 'archived') + ')' : title,
      agent,
    })
  }
  return rows
}

function normalizeZone(value) {
  return value === 'claw' ? 'claw' : 'workspace'
}

function defaultZone(hasClaw) {
  return hasClaw ? 'claw' : 'workspace'
}

function resolveZone(zone) {
  return zone === 'claw' ? 'claw' : 'workspace'
}

function readStoredZone() {
  try {
    const value = typeof localStorage !== 'undefined' ? localStorage.getItem('dar-sidebar-zone') : ''
    return value === 'claw' || value === 'workspace' ? value : ''
  } catch {
    return ''
  }
}

function detectClawZone(doc) {
  if (doc && typeof doc.querySelector === 'function') {
    if (doc.querySelector('[data-dar-zone-switch] [data-zone="claw"][data-active="true"]')) return true
    if (doc.querySelector('[data-dar-zone-switch] [data-zone="workspace"][data-active="true"]')) return false
  }
  return readStoredZone() === 'claw'
}

function agentForSession(projected, sessionId, session) {
  const agents = clawAgents(projected)
  if (sessionId) {
    for (let i = 0; i < agents.length; i++) {
      const ids = agents[i].sessionIds
      if (Array.isArray(ids) && ids.indexOf(sessionId) >= 0) return agents[i]
    }
  }
  const cwd = session && (session.cwd || session.path)
  if (cwd) {
    const key = normalizePathKey(cwd)
    for (let i = 0; i < agents.length; i++) {
      if (agents[i].canonicalRoot && normalizePathKey(agents[i].canonicalRoot) === key) return agents[i]
    }
  }
  return null
}

function boundPresetOf(agent) {
  return agent && agent.dshPreset ? agent.dshPreset : ''
}

function startOfDay(ms) {
  const d = new Date(ms)
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
}

function sessionStamp(updatedAt, now, t) {
  const at = Number(updatedAt)
  if (!Number.isFinite(at) || at <= 0) return ''
  const d = new Date(at)
  const clock = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0')
  const day = startOfDay(now) - startOfDay(at)
  if (day === 0) return clock
  if (day === 86400000) return typeof t === 'function' ? t('timeYesterday') : '昨天'
  const m = d.getMonth() + 1
  const dayNum = d.getDate()
  if (d.getFullYear() === new Date(now).getFullYear()) {
    return typeof t === 'function' ? t('timeMonthDay', { m: m, d: dayNum }) : (m + '月' + dayNum + '日')
  }
  return typeof t === 'function'
    ? t('timeYearMonthDay', { y: d.getFullYear(), m: m, d: dayNum })
    : (d.getFullYear() + '年' + m + '月' + dayNum + '日')
}

function isClawBoundSession(row, agent) {
  if (agent) return true
  return isDsClawPath(row && (row.cwd || row.path))
}

function nextPresetBind() {
  return { action: 'idle', pending: null }
}

function isOfficialSectionLabel(text) {
  const value = String(text || '').trim()
  return value === '工作区' || value === 'Workspaces' || value === '会话' || value === 'Sessions'
}

function normalizeSearchQuery(value) {
  return String(value || '').trim().toLowerCase()
}

function textMatchesQuery(text, query) {
  const q = normalizeSearchQuery(query)
  if (!q) return true
  return String(text || '').toLowerCase().indexOf(q) >= 0
}

function filterClawSearch(agents, query, titleOf) {
  const list = Array.isArray(agents) ? agents : []
  const q = normalizeSearchQuery(query)
  if (!q) {
    return { query: '', agents: list.slice(), forcedOpen: new Set() }
  }
  const out = []
  const forcedOpen = new Set()
  for (let i = 0; i < list.length; i++) {
    const agent = list[i]
    if (!agent) continue
    const nameHit = textMatchesQuery(agent.title || agent.canonicalRoot || agent.agentId, q)
      || textMatchesQuery(agent.slug, q)
    const ids = Array.isArray(agent.sessionIds) ? agent.sessionIds : []
    const keep = []
    for (let s = 0; s < ids.length; s++) {
      const title = typeof titleOf === 'function' ? titleOf(ids[s]) : ''
      if (textMatchesQuery(title, q)) keep.push(ids[s])
    }
    if (!nameHit && keep.length === 0) continue
    const next = Object.assign({}, agent)
    next.sessionIds = nameHit ? ids.slice() : keep
    out.push(next)
    forcedOpen.add(agent.agentId)
  }
  return { query: q, agents: out, forcedOpen }
}

const CLIENT_CODES = {
  REGISTRY_RESPONSE_STALE: 'REGISTRY_RESPONSE_STALE',
}

function newTraceId() {
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    const buf = new Uint8Array(6)
    crypto.getRandomValues(buf)
    let hex = ''
    for (let i = 0; i < buf.length; i++) hex += buf[i].toString(16).padStart(2, '0')
    return 'tr_' + hex
  }
  return 'tr_' + Math.random().toString(16).slice(2, 10) + Date.now().toString(16).slice(-4)
}

function formatObserveFail(data, fallback) {
  const msg = (data && (data.error || data.message)) || fallback || 'failed'
  const code = data && data.code
  const tr = data && data.traceId
  if (code && tr) return msg + '（' + code + ' · ' + tr + '）'
  if (code) return msg + '（' + code + '）'
  return String(msg)
}

const TABS = ['overview', 'persona', 'memory', 'model', 'permissions', 'skills']

function dateStamp(now) {
  const stamp = now instanceof Date ? now : new Date()
  const y = stamp.getFullYear()
  const m = String(stamp.getMonth() + 1).padStart(2, '0')
  const d = String(stamp.getDate()).padStart(2, '0')
  return y + '-' + m + '-' + d
}

function yesterdayStamp(now) {
  const stamp = now instanceof Date ? now : new Date()
  return dateStamp(new Date(stamp.getTime() - 86400000))
}

function coreFiles(daily) {
  const today = (daily && daily.today) || dateStamp()
  const yesterday = (daily && daily.yesterday) || yesterdayStamp()
  return [
    { key: 'agents', file: 'AGENTS.md', via: 'identity' },
    { key: 'soul', file: 'SOUL.md', via: 'identity' },
    { key: 'tools', file: 'TOOLS.md', via: 'identity' },
    { key: 'identity', file: 'IDENTITY.md', via: 'identity' },
    { key: 'user', file: 'USER.md', via: 'memory', vault: 'user' },
    { key: 'heartbeat', file: 'HEARTBEAT.md', via: 'identity' },
    { key: 'memory', file: 'MEMORY.md', via: 'memory', vault: 'memory' },
    { key: 'dailyYesterday', file: 'memory/' + yesterday + '.md', via: 'daily', dateKey: yesterday },
    { key: 'dailyToday', file: 'memory/' + today + '.md', via: 'daily', dateKey: today },
  ]
}

function emptyPersona() {
  return { agents: '', soul: '', tools: '', identity: '', user: '', heartbeat: '', memory: '', dailyToday: '', dailyYesterday: '' }
}

function personaFromFiles(files) {
  const src = files || {}
  return {
    agents: src['AGENTS.md'] || '',
    soul: src['SOUL.md'] || '',
    tools: src['TOOLS.md'] || '',
    identity: src['IDENTITY.md'] || '',
    heartbeat: src['HEARTBEAT.md'] || '',
  }
}

function coreSpec(key, daily) {
  const rows = coreFiles(daily)
  return rows.find((row) => row.key === key) || rows[0]
}

